// 1. Validamos que el ítem y la propiedad existan para evitar el error "undefined"
const rawData = item.json.datos_paciente_texto || "";
const fechaIngresoStr = item.json.fecha_ingreso || "";

// Si no hay datos, devolvemos un objeto vacío pero estructurado para no romper el flujo
if (!rawData) {
    return { error: "No se encontraron datos en datos_paciente_texto" };
}

// 2. Separar por tabulaciones
const columns = rawData.split('\t').map(col => col.trim());

// 3. Procesar Nombres (Lógica: Nombre1 Nombre2 ApellidoP ApellidoM)
const fullParts = columns[0] ? columns[0].split(' ').filter(p => p.length > 0) : [];
const apellidoM = fullParts.length > 2 ? fullParts.pop() : "No especificado";
const apellidoP = fullParts.length > 1 ? fullParts.pop() : "No especificado";
const nombres = fullParts.join(' ') || "No especificado";

// 4. Formatear RUT (Eliminar puntos, mantener guion)
let rutLimpio = (columns[1] || "").replace(/[^0-9kK]/g, '');
let rutFormateado = "No especificado";
if (rutLimpio.length > 1) {
    rutFormateado = `${rutLimpio.slice(0, -1)}-${rutLimpio.slice(-1).toUpperCase()}`;
}

// 5. Cálculo de Fecha de Nacimiento
let fechaNac = "No especificado";
let edadAnios = "No especificado";
const edadString = columns[6] || ""; 
const matchEdad = edadString.match(/(\d+)\s*A\s*(\d+)\s*M\s*(\d+)\s*D/);

if (matchEdad && fechaIngresoStr) {
    try {
        edadAnios = matchEdad[1];
        const meses = parseInt(matchEdad[2]);
        const dias = parseInt(matchEdad[3]);

        // Parsear fecha de ingreso (DD/MM/YYYY HH:mm)
        const partesFecha = fechaIngresoStr.split(' ')[0].split('/');
        if (partesFecha.length === 3) {
            let fechaReferencia = new Date(partesFecha[2], partesFecha[1] - 1, partesFecha[0]);

            fechaReferencia.setFullYear(fechaReferencia.getFullYear() - parseInt(edadAnios));
            fechaReferencia.setMonth(fechaReferencia.getMonth() - meses);
            fechaReferencia.setDate(fechaReferencia.getDate() - dias);

            const dd = String(fechaReferencia.getDate()).padStart(2, '0');
            const mm = String(fechaReferencia.getMonth() + 1).padStart(2, '0');
            const yyyy = fechaReferencia.getFullYear();
            fechaNac = `${dd}-${mm}-${yyyy}`;
        }
    } catch (e) {
        fechaNac = "Error en cálculo";
    }
}

// 6. Retornar el JSON estructurado final
return {
  paciente: {
    nombre: nombres,
    apellido_paterno: apellidoP,
    apellido_materno: apellidoM,
    rut: rutFormateado,
    fechanacimiento: fechaNac,
    prevision: columns[3] || "No especificado",
    edad_anios: edadAnios
  },
  medico: {
    nombre: item.json.nombre_medico || "No especificado",
    rut: item.json.rut_medico || "No especificado"
  },
  metadatos: {
    examenes: item.json.examenes_seleccionados || [],
    fecha_ingreso: fechaIngresoStr,
    modo: item.json.formMode || "no-especificado"
  }
};
